import { ColumnDef, Row } from '@tanstack/react-table';
import ViewIcon from '@/components/icons/ViewIcon';
import { Link } from 'react-router-dom';
import { SalaryList } from '../../types/salary.types';

function fmt(n: number | undefined | null) {
    if (n === undefined || n === null || Number.isNaN(Number(n))) return '—';
    return Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
}

const ActionsCell = ({ row }: { row: Row<SalaryList> }) => {
    return (
        <div className="cursor-pointer flex justify-center">
            <Link to={`/human-resources/salaries-details/${row.original.id}`}>
                <ViewIcon className="text-primery-blue-400" />
            </Link>
        </div>
    );
};

export const columns: ColumnDef<SalaryList>[] = [
    {
        accessorKey: 'name',
        header: () => (
            <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                اسم الموظف
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {row.original.name}
            </div>
        ),
    },
    {
        id: 'employee_code',
        header: () => (
            <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                رقم الموظف
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {row.original.employee_number ?? row.original.id}
            </div>
        ),
    },
    {
        id: 'department',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">الفرع</div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {row.original.branch ?? '—'}
            </div>
        ),
    },
    {
        accessorKey: 'basic_salary',
        header: () => (
            <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                الراتب الأساسي
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {fmt(row.original.basic_salary)}
            </div>
        ),
    },
    {
        accessorKey: 'total_allowances',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">البدلات</div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {fmt(row.original.total_allowances)}
            </div>
        ),
    },
    {
        accessorKey: 'total_rewards',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">المكافآت</div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {fmt(row.original.total_rewards)}
            </div>
        ),
    },
    {
        accessorKey: 'total_deductions',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">الخصومات</div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {fmt(row.original.total_deductions)}
            </div>
        ),
    },
    {
        accessorKey: 'total_salary',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">الإجمالي</div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {fmt(row.original.total_salary)}
            </div>
        ),
    },
    {
        id: 'payment_status',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">الحالة</div>
        ),
        cell: () => (
            <div className="text-xs font-medium tracking-normal leading-[115%] px-4 py-3">
                <p className="border text-primery-blue-50 bg-[#22AD5C] border-[#22AD5C] p-1 w-fit rounded-sm">مدفوع</p>
            </div>
        ),
    },
    {
        id: 'actions',
        header: () => (
            <div className="text-sm text-nowrap text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                التقرير
            </div>
        ),
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
