import { useCallback, useState } from 'react';
import SalariesDetailsList from '../components/salariesDetails/SalariesDetailsList';
import SalariesDetailsStatistics from '../components/statistics/SalariesDetailsStatistics';

export default function SalariesDetailsPage() {
    const [payrollMonth, setPayrollMonth] = useState(() => new Date().getMonth() + 1);
    const [payrollYear, setPayrollYear] = useState(() => new Date().getFullYear());

    const onPayrollMonthYearChange = useCallback((month: number, year: number) => {
        setPayrollMonth(month);
        setPayrollYear(year);
    }, []);

    return (
        <div className="w-full mt-6 mb-20">
            <SalariesDetailsStatistics month={payrollMonth} year={payrollYear} />
            <SalariesDetailsList
                month={payrollMonth}
                year={payrollYear}
                onPayrollMonthYearChange={onPayrollMonthYearChange}
            />
        </div>
    );
}
