import { useCallback, useMemo, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar, type SalariesDetailsToolbarProps } from './data-table-toolbar';
import { columns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { SalaryList } from '../../types/salary.types';

type ToolbarPassThrough = Omit<
    SalariesDetailsToolbarProps,
    'payrollMonth' | 'payrollYear' | 'onPayrollMonthYearChange'
>;

interface Props {
    month: number;
    year: number;
    onPayrollMonthYearChange: (month: number, year: number) => void;
}

export default function SalariesDetailsList({ month, year, onPayrollMonthYearChange }: Props) {
    const [data, setData] = useState<SalaryList[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            setIsLoading(true);
            try {
                const response = await apiGet({
                    endpoint: endpoints.employee.salaryList,
                    queryParams: {
                        page: options.pageIndex + 1,
                        pageSize: options.pageSize,
                        month,
                        year,
                        ...options.filters,
                        search: options.globalFilter,
                    },
                });

                const perPage = response.data.data.pagination.per_page || options.pageSize;
                setData(response.data.data.data);
                setPageCount(Math.ceil(response.data.data.pagination.total / perPage));
                setTotalCount(response.data.data.pagination.total);
            } catch {
                setData([]);
                setPageCount(0);
                setTotalCount(0);
            } finally {
                setIsLoading(false);
            }
        },
        [month, year],
    );

    const Toolbar = useMemo(
        () =>
            function DetailsToolbar(props: ToolbarPassThrough) {
                return (
                    <DataTableToolbar
                        {...props}
                        payrollMonth={month}
                        payrollYear={year}
                        onPayrollMonthYearChange={onPayrollMonthYearChange}
                    />
                );
            },
        [month, year, onPayrollMonthYearChange],
    );

    return (
        <div className="mt-6 mb-20 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                key={`salaries-details-${month}-${year}`}
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={Toolbar}
                isLoading={isLoading}
            />
        </div>
    );
}
